160	const scissorsMarker = "------------------------ >8 ------------------------"
161	
162	// DefaultCommentPrefix is git's comment prefix when core.commentChar is unset.
163	const DefaultCommentPrefix = "#"
164	
165	// autoCommentCandidates are the prefixes git tries, in order, for
166	// core.commentChar=auto.
167	const autoCommentCandidates = "#;@!$%^&|:"
168	
169	// isScissorsLine reports whether line is git's scissors line for commentPrefix.
170	// Git cuts only at that exact line, ended by "\n" alone: never at prose that
171	// mentions the marker, nor at the line an editor saved with CRLF.
172	func isScissorsLine(line, commentPrefix string) bool {
173		return line == commentPrefix+" "+scissorsMarker
174	}
175	
176	// StripEditorComments returns an editor-written commit message without the
177	// lines git's default cleanup drops before the commit is recorded: everything
178	// from the scissors line down, and every line starting with commentPrefix. An
179	// empty commentPrefix, for a -m or -F message whose lines git keeps as
180	// written, returns message unchanged.
181	func StripEditorComments(message, commentPrefix string) string {
182		if commentPrefix == "" {
183			return message
184		}
185		lines := strings.Split(CutAtScissors(message, commentPrefix), "\n")
186		kept := make([]string, 0, len(lines))
187		for _, line := range lines {
188			if !strings.HasPrefix(line, commentPrefix) {
189				kept = append(kept, line)
190			}
191		}
192		return strings.Join(kept, "\n")
193	}
194	
195	// EditorCommentBlockStart returns the index of the line where the comment
196	// block git appends to an editor message starts: the first of the
197	// commentPrefix lines that end the message (blank lines among them included),
198	// or that end it above the scissors line, else the scissors line itself. It
199	// returns -1 when the message ends with no such block, or commentPrefix is
200	// empty. A commentPrefix line followed by other lines is not git's block.
201	func EditorCommentBlockStart(lines []string, commentPrefix string) int {
202		if commentPrefix == "" {
203			return -1
204		}
205		end := slices.IndexFunc(lines, func(line string) bool { return isScissorsLine(line, commentPrefix) })
206		start := end
207		if end < 0 {
208			end = len(lines)
209		}
210		for i := end - 1; i >= 0; i-- {
211			if isCommentLine(lines[i], commentPrefix) {
212				start = i
213			} else if !isBlankLine(lines[i]) {
214				break
215			}
216		}
217		return start
218	}
219	
220	// CutAtScissors returns message without git's scissors line for commentPrefix
221	// and everything below it, which git discards from a `commit -v` message. An
222	// empty commentPrefix returns message unchanged.
223	func CutAtScissors(message, commentPrefix string) string {
224		if commentPrefix == "" {
225			return message
226		}
227		lines := strings.Split(message, "\n")
228		for i, line := range lines {
229			if isScissorsLine(line, commentPrefix) {
230				return strings.Join(lines[:i], "\n")
231			}
232		}
233		return message
234	}
235	
236	// AutoCommentPrefix returns the prefix git chose for core.commentChar=auto: the
237	// first of autoCommentCandidates that starts no line of the message, picked
238	// before git adds its comment block. When git wrote that block into message
239	// (hasBlock), its lines start with the choice, so it is read back from them:
240	// the scissors line if there is one, else the comment lines that end the
241	// message.
242	func AutoCommentPrefix(message string, hasBlock bool) string {
243		lines := strings.Split(message, "\n")
244		if hasBlock {
245			for _, line := range lines {
246				for _, candidate := range autoCommentCandidates {
247					if isScissorsLine(line, string(candidate)) {
248						return string(candidate)
249					}
250				}
251			}
252			for i := len(lines) - 1; i >= 0; i-- {
253				if isBlankLine(lines[i]) {
254					continue
255				}
256				if first := lines[i][:1]; strings.Contains(autoCommentCandidates, first) {
257					return first
258				}
259				break
260			}
261		}
262		// Git treats a CR as a line start too.
263		starts := make(map[byte]bool)
264		for _, line := range strings.FieldsFunc(message, func(r rune) bool { return r == '\n' || r == '\r' }) {
265			starts[line[0]] = true
266		}
267		for i := range len(autoCommentCandidates) {
268			if !starts[autoCommentCandidates[i]] {
269				return autoCommentCandidates[i : i+1]
270			}
271		}
272		return DefaultCommentPrefix
273	}
274	
275	// RemoveCheckpointTrailers removes every whole Entire-Checkpoint trailer line
276	// whose ID drop selects, anywhere between the subject paragraph and a scissors
277	// line, and returns the new message with the IDs removed (nil when the
278	// message is unchanged). It does not try to reproduce git's trailer-block
279	// rules (mixed blocks, a "(cherry picked from ...)" note, custom comment
280	// characters): a line that is exactly a checkpoint trailer is one in every
281	// form git accepts, and leaving one behind would let an amend keep a deleted
282	// checkpoint alive. Indentation is ignored, since a squash message indents
283	// the squashed commits' messages. Prose that merely mentions an ID is not a
284	// whole trailer line and stays. Blank lines a removal leaves doubled are
285	// collapsed, and trailing blank lines are trimmed unless a scissors line
286	// follows; nothing at or below the scissors line is touched.
287	func RemoveCheckpointTrailers(message string, drop func(checkpointID.CheckpointID) bool) (string, []checkpointID.CheckpointID) {
288		lines := strings.Split(message, "\n")
289		bodyStart := subjectParagraphEnd(lines)
290		end := slices.IndexFunc(lines, func(line string) bool { return strings.Contains(line, scissorsMarker) })
291		hasScissors := end >= 0
292		if !hasScissors {
293			end = len(lines)
294		}
295		removeLine := make([]bool, end)
296		var removed []checkpointID.CheckpointID
297		for i := bodyStart; i < end; i++ {
298			match := checkpointTrailerLineRegex.FindStringSubmatch(strings.TrimSpace(lines[i]))
299			if match == nil {
300				continue
301			}
302			cpID, err := checkpointID.NewCheckpointID(match[1])
303			if err != nil || !drop(cpID) {
304				continue
305			}
306			removeLine[i] = true
307			if !slices.Contains(removed, cpID) {
308				removed = append(removed, cpID)
309			}
310		}
311		if len(removed) == 0 {
312			return message, nil
313		}
314		if hasScissors {
315			kept := keepLines(lines[:end], removeLine, false, false)
316			return strings.Join(append(kept, lines[end:]...), "\n"), removed
317		}
318		return strings.Join(keepLines(lines, removeLine, true, strings.HasSuffix(message, "\n")), "\n"), removed
319	}
320	
321	// subjectParagraphEnd returns the index just past the subject paragraph: the
322	// first run of non-blank lines.
323	func subjectParagraphEnd(lines []string) int {
324		i := 0
325		for i < len(lines) && isBlankLine(lines[i]) {
326			i++
327		}
328		for i < len(lines) && !isBlankLine(lines[i]) {
329			i++
330		}
331		return i
332	}
333	
334	// keepLines drops the removed lines and collapses a blank line that a
335	// removal would leave doubled. With trimTrailing it also trims trailing blank
336	// lines, keeping the message's final newline.
337	func keepLines(lines []string, removeLine []bool, trimTrailing, endsWithNewline bool) []string {
338		kept := make([]string, 0, len(lines))
339		afterRemoval := false
340		for i, line := range lines {
341			if removeLine[i] {
342				afterRemoval = true
343				continue
344			}
345			blank := isBlankLine(line)
346			if blank && afterRemoval && len(kept) > 0 && isBlankLine(kept[len(kept)-1]) {
347				continue
348			}
349			if !blank {
350				afterRemoval = false
351			}
352			kept = append(kept, line)
353		}
354		if !trimTrailing {
355			return kept
356		}
357		for len(kept) > 0 && isBlankLine(kept[len(kept)-1]) {
358			kept = kept[:len(kept)-1]
359		}
360		if endsWithNewline {
361			kept = append(kept, "")
362		}
363		return kept
364	}
365	
366	func isBlankLine(line string) bool {
367		return strings.TrimSpace(line) == ""
368	}
369	
370	// FormatCheckpoint creates a commit message with a checkpoint trailer.
371	// This links user commits to their checkpoint metadata on entire/checkpoints/v1 branch.
372	func FormatCheckpoint(message string, cpID checkpointID.CheckpointID) string {
373		return fmt.Sprintf("%s\n\n%s: %s\n", message, CheckpointTrailerKey, cpID.String())
374	}
375	
376	// trailerLineRe matches git trailer format: "Key-Name:" at the start of the
377	// line, with no space before the colon. Like git, it accepts any separator
378	// after the colon ("Key:value", a tab), which also makes a line starting with a
379	// URL ("https://...") trailer-shaped.
380	var trailerLineRe = regexp.MustCompile(`^[A-Za-z][A-Za-z0-9-]*:`)
381	
382	// IsTrailerLine reports whether a line matches git trailer format.
383	func IsTrailerLine(line string) bool {
384		return trailerLineRe.MatchString(line)
385	}
386	
387	// appendTrailerLine appends a single pre-formatted trailer line (e.g. "Key: value")
388	// to message in trailer-block-aware format: it is joined to a final paragraph
389	// that is a trailer block (see isTrailerBlock), and otherwise starts a new block
390	// after a blank line.
391	func appendTrailerLine(message, trailerLine string) string {
392		trimmed := strings.TrimRight(message, "\n")
393	
394		// Collect the final paragraph. Joining also requires a blank line above
395		// the paragraph so a trailer-shaped subject line (e.g. "fix: bug") never
396		// has the trailer glued onto it.
397		lines := strings.Split(trimmed, "\n")
398		start := len(lines)
399		separated := false
400		for start > 0 {
401			if strings.TrimSpace(lines[start-1]) == "" {
402				separated = true
403				break
404			}
405			start--
406		}
407	
408		// Join only a block with no other lines, read without a comment prefix:
409		// every reader accepts it whatever prefix it skips, and the trailer never
410		// lands after prose or a kept "#" line.
411		if trailerLines, otherLines, _ := countTrailerBlock(lines[start:], ""); separated && trailerLines > 0 && otherLines == 0 {
412			return trimmed + "\n" + trailerLine + "\n"
413		}
414		return trimmed + "\n\n" + trailerLine + "\n"
415	}
416	
417	// AppendCheckpointTrailer appends Entire-Checkpoint in trailer-aware format
418	// (see appendTrailerLine).
419	func AppendCheckpointTrailer(message, checkpointID string) string {
420		trailer := fmt.Sprintf("%s: %s", CheckpointTrailerKey, checkpointID)
421		return appendTrailerLine(message, trailer)
422	}
423	
424	// HasOPFApplied reports whether the commit message carries an
425	// `Entire-OPF-Applied: true` trailer. Any other value (or absence) is
426	// treated as "OPF not applied" so the pre-push rewrite considers the
427	// commit a candidate for OPF redaction. Pinning the value to literal
428	// "true" — rather than just trailer presence — prevents a future
429	// "Entire-OPF-Applied: false" or "skipped" from accidentally meaning
430	// "yes, applied."
431	func HasOPFApplied(commitMessage string) bool {
432		for _, line := range finalTrailerBlock(commitMessage, "") {
433			key, value, ok := strings.Cut(line, ":")
434			if !ok || key != OPFAppliedTrailerKey {
435				continue
436			}
437			if strings.TrimSpace(value) == OPFAppliedTrailerValue {
438				return true
439			}
440		}
441		return false
442	}
443	
444	// finalTrailerBlock returns the trailer and continuation lines of message's
445	// final trailer block, skipping lines that start with commentPrefix as git's
446	// trailer grammar does, or nil when the final paragraph is not a trailer block.
447	func finalTrailerBlock(message, commentPrefix string) []string {
448		lines := strings.Split(message, "\n")
449		// Git ignores the blank and comment lines that end a message.
450		end := len(lines)
451		for end > 0 && (isBlankLine(lines[end-1]) || isCommentLine(lines[end-1], commentPrefix)) {
452			end--
453		}
454		start := end
455		for start > 0 && !isBlankLine(lines[start-1]) {
456			start--
457		}
458		// Git reads the first paragraph as the subject, never as trailers.
459		if start == 0 || !isTrailerBlock(lines[start:end], commentPrefix) {
460			return nil
461		}
462		return slices.DeleteFunc(lines[start:end], func(line string) bool { return isCommentLine(line, commentPrefix) })
463	}
464	
465	// gitGeneratedPrefixes start the lines git itself adds to a trailer block
466	// (`commit -s`, `cherry-pick -x`).
467	var gitGeneratedPrefixes = []string{"Signed-off-by: ", "(cherry picked from commit "}
468	
469	// isTrailerBlock reports whether lines form a trailer block by git's rule: at
470	// least one trailer line, with every other line an indented continuation of a
471	// trailer's value or a line starting with commentPrefix, which git skips. A
472	// block holding a line git generates may also hold other lines, as long as
473	// they are at most three times its trailer lines.
474	func isTrailerBlock(lines []string, commentPrefix string) bool {
475		trailerLines, otherLines, generated := countTrailerBlock(lines, commentPrefix)
476		return trailerLines > 0 && (otherLines == 0 || generated && trailerLines*3 >= otherLines)
477	}
478	
479	// countTrailerBlock counts lines' trailer lines and other lines the way git's
480	// trailer grammar does, and reports whether one is a line git generates. Both
481	// isTrailerBlock and appendTrailerLine classify with this so the writer never
482	// joins onto a paragraph the readers reject.
483	func countTrailerBlock(lines []string, commentPrefix string) (trailerLines, otherLines int, generated bool) {
484		continuable := false
485		for _, line := range lines {
486			switch {
487			case isCommentLine(line, commentPrefix):
488				// Git skips the line, and an indented line after it continues
489				// nothing.
490				continuable = false
491			case slices.ContainsFunc(gitGeneratedPrefixes, func(prefix string) bool { return strings.HasPrefix(line, prefix) }):
492				trailerLines++
493				generated, continuable = true, true
494			case IsTrailerLine(line):
495				trailerLines++
496				continuable = true
497			case continuable && (strings.HasPrefix(line, " ") || strings.HasPrefix(line, "\t")):
498				// Git treats an indented line after a trailer as a continuation
499				// of that trailer's value, never as a new trailer.
500			default:
501				otherLines++
502				continuable = false
503			}
504		}
505		return trailerLines, otherLines, generated
506	}
507	
508	func isCommentLine(line, commentPrefix string) bool {
509		return commentPrefix != "" && strings.HasPrefix(line, commentPrefix)
510	}
511	
512	// AppendOPFAppliedTrailer appends `Entire-OPF-Applied: true` in
513	// trailer-aware format. Idempotent: if the message already carries
514	// the trailer with value "true", the original message is returned
515	// unchanged so re-parenting an already-applied commit doesn't
516	// duplicate the trailer.
517	func AppendOPFAppliedTrailer(message string) string {
518		if HasOPFApplied(message) {
519			return message
520		}
521		trailer := fmt.Sprintf("%s: %s", OPFAppliedTrailerKey, OPFAppliedTrailerValue)
522		return appendTrailerLine(message, trailer)
523	}

