// CommitMsg is called by the git commit-msg hook after the user edits the message.
// If the message contains only our trailer (no actual user content), strip it
// so git will abort the commit due to empty message.

func (s *ManualCommitStrategy) CommitMsg(ctx context.Context, commitMsgFile string) error { //nolint:unparam // error return is part of the hook contract; callers check it
	content, err := os.ReadFile(commitMsgFile) //nolint:gosec // Path comes from git hook
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	message := string(content)

	// Check if our trailer is present (ParseCheckpoint validates format, so found==true means valid)
	if _, found := trailers.ParseCheckpoint(message); !found {
		// No trailer, nothing to do
		return nil
	}

	// Check if there's any user content (non-comment, non-trailer lines)
	if !hasUserContent(message, gitCommentConfig(ctx)) {
		// No user content - strip the trailer so git aborts
		message = stripCheckpointTrailer(message)
		if err := os.WriteFile(commitMsgFile, []byte(message), 0o600); err != nil {
			return nil //nolint:nilerr // Hook must be silent on failure
		}
	}

	return nil
}

// PostRewrite is called by the git post-rewrite hook after amend/rebase
// operations. It keeps session linkage aligned with rewritten commit SHAs in
// the current worktree.
func (s *ManualCommitStrategy) PostRewrite(ctx context.Context, rewriteType string, r io.Reader) error {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	if rewriteType != "amend" && rewriteType != "rebase" {
		logging.Debug(logCtx, "post-rewrite: unsupported rewrite type, skipping",
			slog.String("rewrite_type", rewriteType),
		)
		return nil
	}

	rewrites, err := parsePostRewritePairs(r)
	if err != nil {
		return err
	}
	if len(rewrites) == 0 {
		return nil
	}

	// Best-effort: a hook must not fail the user's amend or rebase.
	worktreePath, err := paths.WorktreeRoot(ctx)
	if err != nil {
		logging.Debug(logCtx, "post-rewrite: no worktree root, skipping",
			slog.String("error", err.Error()))
		return nil
	}

	sessions, err := s.findSessionsForWorktree(ctx, worktreePath)
	if err != nil {
		logging.Debug(logCtx, "post-rewrite: could not list sessions, skipping",
			slog.String("error", err.Error()))
		return nil
	}
	if len(sessions) == 0 {
		return nil
	}

	for _, sess := range sessions {
		sessionID := sess.SessionID
		mutErr := MutateSessionState(ctx, sessionID, func(state *SessionState) error {
			if !remapSessionForRewrite(state, rewrites) {
				return ErrMutationSkip
			}
			logging.Info(logCtx, "post-rewrite: remapped session linkage",
				slog.String("session_id", state.SessionID),
				slog.String("rewrite_type", rewriteType),
				slog.String("base_commit", truncateHash(state.BaseCommit)),
			)
			return nil
		})
		if mutErr != nil && !errors.Is(mutErr, ErrStateNotFound) {
			logging.Warn(logCtx, "post-rewrite: failed to remap session linkage",
				slog.String("session_id", sessionID),
				slog.String("error", mutErr.Error()),
			)
		}
	}

	return nil
}

func parsePostRewritePairs(r io.Reader) ([]rewritePair, error) {
	scanner := bufio.NewScanner(r)
	var pairs []rewritePair
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		fields := strings.Fields(line)
		if len(fields) < 2 {
			return nil, fmt.Errorf("invalid post-rewrite mapping line: %q", line)
		}
		pairs = append(pairs, rewritePair{
			OldSHA: fields[0],
			NewSHA: fields[1],
		})
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("scan post-rewrite input: %w", err)
	}
	return pairs, nil
}

// hasUserContent reports whether git will record anything in message besides
// Entire-Checkpoint trailers and the sign-offs git's empty check skips. git
// does not tell commit-msg how the message was written, so the message has to
// say: an editor message ends with git's comment block or carries
// prepare-commit-msg's explanation, whose prefix is the one git cleans with; a
// -m/-F message has neither. Comment lines then count as git's cleanup mode
// treats them (see dropsComments), and the scissors line and everything below
// it never count. A user who deletes both and types only comment lines is
// therefore read as having content.
func hasUserContent(message string, cfg commentConfig) bool {
	commentPrefix, explained := explanationPrefix(message)
	if !explained {
		commentPrefix = cfg.prefixFor(message, true)
	}
	message = trailers.CutAtScissors(message, commentPrefix)
	if cfg.dropsComments(explained || strings.HasPrefix(lastNonBlankLine(message), commentPrefix)) {
		message = trailers.StripEditorComments(message, commentPrefix)
	}
	trailerPrefix := trailers.CheckpointTrailerKey + ":"
	for _, line := range strings.Split(message, "\n") {
		trimmed := strings.TrimSpace(line)
		if trimmed != "" && !strings.HasPrefix(trimmed, trailerPrefix) && !strings.HasPrefix(line, signOffPrefix) {
			return true
		}
	}
	return false
}

// signOffPrefix starts the `commit -s` lines git's empty-message check skips.
const signOffPrefix = "Signed-off-by: "

// explanationPrefix returns the comment prefix prepare-commit-msg wrote its
// explanation with, and whether the message carries that explanation.
func explanationPrefix(message string) (string, bool) {
	for _, line := range strings.Split(message, "\n") {
		if prefix, _, ok := strings.Cut(line, trailerExplanation); ok && prefix != "" {
			return prefix, true
		}
	}
	return "", false
}

// lastNonBlankLine returns the last line of message that is not blank, or ""
// when there is none.
func lastNonBlankLine(message string) string {
	lines := strings.Split(message, "\n")
	for i := len(lines) - 1; i >= 0; i-- {
		if strings.TrimSpace(lines[i]) != "" {
			return lines[i]
		}
	}
	return ""
}

// stripCheckpointTrailer removes the Entire-Checkpoint trailer line from the message.
func stripCheckpointTrailer(message string) string {
	trailerPrefix := trailers.CheckpointTrailerKey + ":"
	var result []string
	for _, line := range strings.Split(message, "\n") {
		if !strings.HasPrefix(strings.TrimSpace(line), trailerPrefix) {
			result = append(result, line)
		}
	}
	return strings.Join(result, "\n")
}

// isGitSequenceOperation checks if git is currently in the middle of a rebase,
// cherry-pick, or revert operation. During these operations, commits are being
// replayed and should not be linked to agent sessions.
//
// Detects:
//   - rebase: .git/rebase-merge/ or .git/rebase-apply/ directories
//   - cherry-pick: .git/CHERRY_PICK_HEAD file
//   - revert: .git/REVERT_HEAD file
func isGitSequenceOperation(ctx context.Context) bool {
	// Get git directory (handles worktrees and relative paths correctly)
	gitDir, err := GetGitDir(ctx)
	if err != nil {
		return false // Can't determine, assume not in sequence operation
	}

	// These markers live in the PER-WORKTREE git dir, not the common dir, which
	// is why this opens gitDir rather than using gitdir.Open.
	root, err := gitdir.OpenAt(gitDir)
	if err != nil {
		return false // Can't determine, assume not in sequence operation
	}

	// Check for rebase state directories, then cherry-pick and revert state files.
	for _, marker := range []string{"rebase-merge", "rebase-apply", "CHERRY_PICK_HEAD", "REVERT_HEAD"} {
		if _, err := root.Lstat(marker); err == nil {
			return true
		}
	}

	return false
}

// GitOperationInProgress names the git operation the worktree is in the middle
// of (rebase or am, cherry-pick, revert, merge, bisect), or returns "" when
// none is. A command about to move a branch must not do so mid-operation. A
// git dir that can't be read reports none, as isGitSequenceOperation does.
func GitOperationInProgress(ctx context.Context) string {
	gitDir, err := GetGitDir(ctx)
	if err != nil {
		return ""
	}
	// Per-worktree markers; see isGitSequenceOperation.
	root, err := gitdir.OpenAt(gitDir)
	if err != nil {
		return ""
	}
	for _, m := range []struct{ marker, op string }{
		{"rebase-merge", "a rebase"},
		{"rebase-apply", "a rebase or am"},
		{"CHERRY_PICK_HEAD", "a cherry-pick"},
		{"REVERT_HEAD", "a revert"},
		{"MERGE_HEAD", "a merge"},
		{"BISECT_LOG", "a bisect"},
	} {
		if _, err := root.Lstat(m.marker); err == nil {
			return m.op
		}
	}
	return ""
}

