 71	// pickCondensationTarget chooses the trailer a commit's new work condenses
 72	// into. A lone trailer is it. Among several, trailers that already have a
 73	// checkpoint are links; the stamped one is the last without a checkpoint,
 74	// since prepare appends after the inherited ones. None means the commit only
 75	// links existing work.
 76	func pickCondensationTarget(ids []id.CheckpointID, exists func(id.CheckpointID) bool) (id.CheckpointID, bool) {
 77		if len(ids) == 1 {
 78			return ids[0], true
 79		}
 80		for i := len(ids) - 1; i >= 0; i-- {
 81			if !exists(ids[i]) {
 82				return ids[i], true
 83			}
 84		}
 85		return id.EmptyCheckpointID, false
 86	}
