 88	func pickCondensationTargetState(ids []id.CheckpointID, exists func(id.CheckpointID) bool) (target id.CheckpointID, preexisting, found bool) {
 89		if len(ids) == 0 {
 90			return id.EmptyCheckpointID, false, false
 91		}
 92		if len(ids) == 1 {
 93			return ids[0], exists(ids[0]), true
 94		}
 95		target, found = pickCondensationTarget(ids, exists)
 96		if !found {
 97			// Every trailer already has a checkpoint: an amend of a squash whose
 98			// inherited-trailer marker the first post-commit consumed. The stamp is
 99			// the last trailer; as a preexisting target, only the session amending
100			// it (its LastCheckpointID) may write there, exactly as for a lone one.
101			return ids[len(ids)-1], true, true
102		}
103		// Recheck after selection: another session may have created the checkpoint
104		// between the first store read and condensation.
105		return target, exists(target), true
106	}
