108	// condensationTarget picks the trailer this commit condenses into and reports
109	// whether that checkpoint already existed before this post-commit began. Read
110	// once per commit: sessions condensing into the same fresh checkpoint later in
111	// this hook must not look like writes into someone else's.
112	func (s *ManualCommitStrategy) condensationTarget(ctx context.Context, repo *git.Repository, ids []id.CheckpointID) (target id.CheckpointID, preexisting, found bool) {
113		if len(ids) == 0 {
114			return id.EmptyCheckpointID, false, false
115		}
116		store, err := s.getPersistentStore(ctx, repo)
117		if err != nil {
118			// Nothing can be told apart without a store; the last trailer is
119			// where prepare stamps.
120			return ids[len(ids)-1], false, true
121		}
122		exists := func(cpID id.CheckpointID) bool { return checkpointExists(ctx, store, cpID) }
123		target, preexisting, ok := pickCondensationTargetState(ids, exists)
124		return target, preexisting, ok
125	}
