343		if len(inherited) == 0 {
344			return ids
345		}
346		out := make([]id.CheckpointID, 0, len(ids))
347		for _, cpID := range ids {
348			if !inherited[cpID] {
349				out = append(out, cpID)
350			}
351		}
352		return out
