	obj := repo.Storer.NewEncodedObject()

// readMetadataFromBlob reads Metadata from a blob hash.
func (s *treeWriter) readMetadataFromBlob(hash plumbing.Hash) (*Metadata, error) {
	return readJSONFromBlob[Metadata](s.repo, hash)
}

// buildCommitMessage constructs the commit message with proper trailers.
// The commit subject is always "Checkpoint: <id>" for consistency.
// If CommitSubject is provided, it's included in the body.
//
// No task-metadata trailer is written here: the old single-task-per-checkpoint
// route (Entire-Metadata-Task) fed it from the now-deleted IsTask/ToolUseID
// fields, which no producer ever set — this trailer was always absent on real
// checkpoints.
// opts.Tasks can now name several tasks in one checkpoint, so there is no
// single path to trailer-point at even in principle.
func (s *treeWriter) buildCommitMessage(opts WriteOptions) string {
	var commitMsg strings.Builder

	// Subject line is always the checkpoint ID for consistent formatting
	fmt.Fprintf(&commitMsg, "Checkpoint: %s\n\n", opts.CheckpointID)

	// Include custom description in body if provided
	if opts.CommitSubject != "" {
		commitMsg.WriteString(opts.CommitSubject + "\n\n")
	}
	fmt.Fprintf(&commitMsg, "%s: %s\n", trailers.SessionTrailerKey, opts.SessionID)
	fmt.Fprintf(&commitMsg, "%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy)
	if opts.Agent != "" {
		fmt.Fprintf(&commitMsg, "%s: %s\n", trailers.AgentTrailerKey, opts.Agent)
	}

	return commitMsg.String()
}

// Read reads a committed checkpoint's summary by ID from the entire/checkpoints/v1 branch.
// Returns only the CheckpointSummary (paths + aggregated stats), not actual content.
// Use ReadSessionContent to read actual transcript/prompts/context.
// Returns nil, nil if the checkpoint doesn't exist.
//
// The storage format uses numbered subdirectories for each session (0-based):
//

	} else {
		lines = append(lines, "Their SHAs change; their content doesn't.")
	}
	if len(checkedRemotes) > 0 {
		lines = append(lines, fmt.Sprintf("It isn't on %s. If you pushed it somewhere else, rewriting it means a force-push there.", strings.Join(checkedRemotes, ", ")))
	}
	if others := otherRefsContaining(ctx, target); len(others) > 0 {
		lines = append(lines, "These keep the old commits: "+strings.Join(others, ", "))
	}
	for _, c := range chain {
		if c.Signature != "" {
			lines = append(lines, "Signed commits lose their signatures.")
			break
		}
	}
	return lines
}

// otherRefsContaining lists the branches and tags, other than the checked-out
// branch, that contain target.
func otherRefsContaining(ctx context.Context, target *object.Commit) []string {
	current, _ := exec.CommandContext(ctx, "git", "symbolic-ref", "-q", "--short", "HEAD").Output() //nolint:errcheck // detached HEAD has none
	out, err := exec.CommandContext(ctx, "git", "for-each-ref", "--contains", target.Hash.String(), "--format=%(refname:short)", "refs/heads", "refs/tags").Output()
	if err != nil {
		return nil
	}
	var refs []string
	for _, ref := range strings.Fields(string(out)) {
		if ref != strings.TrimSpace(string(current)) {
			refs = append(refs, ref)
		}
	}
	return refs
}

// rewriteWithTrailer adds the checkpoint trailer to chain[0] and replays the
// rest of chain on top, keeping every tree, author, committer and message (as
// git filter-branch does), then moves the
// checked-out branch (or a detached HEAD) to the new tip if it is still at the
// old one. Trees are reused, so the worktree and index are untouched, and no
// commit hooks run. Session state that names the old commits is remapped as
// git's post-rewrite hook would.
func rewriteWithTrailer(ctx context.Context, w io.Writer, chain []*object.Commit, checkpointID id.CheckpointID) error {
	oldHead := chain[len(chain)-1].Hash.String()
	var pairs strings.Builder
	parents := chain[0].ParentHashes
	newSHA, targetSHA := "", ""
	for i, c := range chain {
		message := c.Message
		if i == 0 {
			message = trailers.AppendCheckpointTrailer(message, checkpointID.String())
		}
		args := []string{"commit-tree", c.TreeHash.String()}
		if i == 0 {
			for _, p := range parents {
				args = append(args, "-p", p.String())
			}
		} else {
			args = append(args, "-p", newSHA)
		}
		cmd := exec.CommandContext(ctx, "git", args...)
		cmd.Stdin = strings.NewReader(message)
		cmd.Env = append(withoutIdentityEnv(os.Environ()),
			"GIT_AUTHOR_NAME="+c.Author.Name,
			"GIT_AUTHOR_EMAIL="+c.Author.Email,
			fmt.Sprintf("GIT_AUTHOR_DATE=@%d %s", c.Author.When.Unix(), c.Author.When.Format("-0700")),
			"GIT_COMMITTER_NAME="+c.Committer.Name,
			"GIT_COMMITTER_EMAIL="+c.Committer.Email,
			fmt.Sprintf("GIT_COMMITTER_DATE=@%d %s", c.Committer.When.Unix(), c.Committer.When.Format("-0700")),
		)
		var stderr bytes.Buffer
		cmd.Stderr = &stderr
		out, err := cmd.Output()
		if err != nil {
			return fmt.Errorf("rewrite commit %s: %w: %s", c.Hash.String()[:12], err, strings.TrimSpace(stderr.String()))
		}
		newSHA = strings.TrimSpace(string(out))
		if i == 0 {
			targetSHA = newSHA
		}
		fmt.Fprintf(&pairs, "%s %s\n", c.Hash, newSHA)
	}

	reason := "entire session attach: add Entire-Checkpoint " + checkpointID.String() + " to " + chain[0].Hash.String()[:12]
	updateArgs := []string{"update-ref", "-m", reason}
	if branch, err := exec.CommandContext(ctx, "git", "symbolic-ref", "-q", "HEAD").Output(); err == nil {
		updateArgs = append(updateArgs, strings.TrimSpace(string(branch)))
	} else {
		updateArgs = append(updateArgs, "--no-deref", "HEAD")
	}
	updateArgs = append(updateArgs, newSHA, oldHead)

	if !shouldFallBackToCommitResolution(checkpointErr) {
		return checkpointErr
	}
	logging.Debug(ctx, "explain auto: checkpoint lookup failed, trying commit fallback",
		slog.String("target", target),
		slog.String("checkpoint_error", checkpointErr.Error()))

	if lookupErr != nil {
		// Composed message beats errors.Join here — the latter renders
		// two lines (one per error) and users act on the first/stale one.
		return fmt.Errorf("no checkpoint matched %q, and commit fallback failed: %w", target, lookupErr)
	}
	hash, ambiguousMatches, resolveErr := resolveCommitUnambiguous(lookup.repo, target)
	if resolveErr != nil {
		if errors.Is(resolveErr, errAmbiguousCommitPrefix) {
			renderAmbiguousPrefixFailure(errW, target, "commits", buildAmbiguousCommitMatches(lookup.repo, ambiguousMatches))
			return NewSilentError(resolveErr)
		}
		logging.Debug(ctx, "explain auto: git ref resolution failed",
			slog.String("target", target),
			slog.String("error", resolveErr.Error()))
		return fmt.Errorf("no checkpoint or commit found matching %q", target)
	}
	commit, commitErr := lookup.repo.CommitObject(hash)
	if commitErr != nil {
		return fmt.Errorf("failed to get commit %s: %w", abbreviateCommitHash(lookup.repo, hash), commitErr)
	}
	cpID, hasCheckpoint := checkpointForCommit(ctx, commit.Message, generate)
	linkVia := "its Entire-Checkpoint trailer"
	if !hasCheckpoint {
		// A commit linked by `entire session attach --commit` carries no
		// trailer; its checkpoint names it instead. Most recent wins.
		if linked := checkpoint.CheckpointsLinkedToWithStubs(ctx, lookup.store, lookup.committed, hash.String(), commit.Committer.When); len(linked) > 0 {
			cpID, hasCheckpoint = linked[0], true
			linkVia = "a link recorded by entire session attach"
			fmt.Fprintf(errW, "Note: commit %s has no Entire-Checkpoint trailer; checkpoint %s names it in a link recorded by entire session attach. The CLI can't verify who recorded the link: anyone who can push checkpoints can name any commit.\n", abbreviateCommitHash(lookup.repo, hash), cpID)
		}
	}
	if !hasCheckpoint {
		// Side-effect modes must error — silently succeeding would leave
		// scripts unable to distinguish "done" from "didn't happen".
		if generate || rawTranscript {
			return fmt.Errorf("cannot %s: commit %s has no Entire-Checkpoint trailer", generateOrRawLabel(generate), abbreviateCommitHash(lookup.repo, hash))
		}
		printNoTrailerMessage(w, lookup.repo, hash)
		return nil
	}
	logging.Debug(ctx, "explain auto: resolved commit to checkpoint via trailer",
		slog.String("target", target),
		slog.String("commit", abbreviateCommitHash(lookup.repo, hash)),
		slog.String("checkpoint_id", cpID.String()))
	if err := runExplainCheckpointWithLookup(ctx, w, errW, cpID.String(), noPager, verbose, full, rawTranscript, generate, force, searchAll, lookup, nil, summaryTimeoutSeconds); err != nil {
		return trailerCheckpointError(ctx, lookup.repo, hash, cpID, linkVia, err)
	}
	return nil
}

// runExplainAutoAmbiguityGuard refuses --generate when the positional
// target resolves as both a git revision and a committed-checkpoint prefix.
// Writing a summary to the wrong checkpoint is destructive; read-only flows
// tolerate the same ambiguity by preferring the checkpoint path.
//
// Best-effort: on repo/list failures we return nil so the main flow
// surfaces the real error instead of double-reporting.
func runExplainAutoAmbiguityGuard(ctx context.Context, target string, lookup *explainCheckpointLookup, lookupErr error) error {
	// Targets longer than the longest possible checkpoint ID (a 26-char ULID)
	// can't be a prefix of one, so they can't be an ambiguous checkpoint target.
	if len(target) > id.MaxIDLength {
		return nil
	}
	if lookupErr != nil {
		return fmt.Errorf("not a git repository: %w", err)
	}
	defer repo.Close()

	// Resolve the commit reference, erroring on hex-prefix ambiguity
	// instead of silently picking the first matching commit.
	hash, ambiguousMatches, err := resolveCommitUnambiguous(repo, commitRef)
	if err != nil {
		if errors.Is(err, errAmbiguousCommitPrefix) {
			renderAmbiguousPrefixFailure(errW, commitRef, "commits", buildAmbiguousCommitMatches(repo, ambiguousMatches))
			return NewSilentError(err)
		}
		return renderExplainFailure(errW, "Commit not found", []explainRow{
			{Label: "ref", Value: commitRef},
		}, fmt.Errorf("commit not found: %s", commitRef))
	}

	commit, err := repo.CommitObject(hash)
	if err != nil {
		return fmt.Errorf("failed to get commit: %w", err)
	}

	// Extract Entire-Checkpoint trailer
	checkpointID, hasCheckpoint := checkpointForCommit(ctx, commit.Message, generate)
	if !hasCheckpoint {
		// Side-effect modes must error so scripts can distinguish "done"
		// from "didn't happen"; read-only modes print a friendly message.
		if generate || rawTranscript {
			return fmt.Errorf("cannot %s: commit %s has no Entire-Checkpoint trailer", generateOrRawLabel(generate), abbreviateCommitHash(repo, hash))
		}
		printNoTrailerMessage(w, repo, hash)
		return nil
	}

	// Delegate to checkpoint detail view, forwarding the full flag set so
	// --generate / --raw-transcript / --force work via --commit as well.
	if err := runExplainCheckpoint(ctx, w, errW, checkpointID.String(), noPager, verbose, full, rawTranscript, generate, force, searchAll, summaryTimeoutSeconds); err != nil {
		return trailerCheckpointError(ctx, repo, hash, checkpointID, "its Entire-Checkpoint trailer", err)
	}
	return nil
}

// checkpointForCommit returns the checkpoint a commit's trailer names.
// --generate writes a summary into it, so only the final trailer block counts
// there, and its last ID, the one attach joins: inherited trailers come before
// the one prepare stamped. Read-only views also find IDs elsewhere in the
// message, where squash commits carry their squashed commits' trailers.
func checkpointForCommit(ctx context.Context, message string, generate bool) (id.CheckpointID, bool) {
	if generate {
		if ids := strategy.FinalCheckpointTrailers(ctx, message); len(ids) > 0 {
			return ids[len(ids)-1], true
		}
		return id.EmptyCheckpointID, false
	}
	return trailers.ParseCheckpoint(message)
}

// trailerCheckpointError attributes a checkpoint failure to the commit whose
// Entire-Checkpoint trailer named it. Commits keep their trailers when
// `entire checkpoint delete` removes a checkpoint, so a miss on an ID this
// clone deleted says so; any other miss stays a plain not-found.

// and is it pushed — never from a flag or from whether it is HEAD.
type attachLinkMode int

const (
	// attachJoinExisting: the commit's final trailer block already carries an
	// Entire-Checkpoint trailer; the session joins that checkpoint and history
	// is unchanged.
	attachJoinExisting attachLinkMode = iota
	// attachAddTrailer: no remote branch holds the commit. The trailer is
	// added, rewriting the commit and any after it: nobody else has them, and
	// a trailer survives a later rebase, where a recorded link wouldn't.
	attachAddTrailer
	// attachRecordLink: a remote branch already holds the commit, so rewriting
	// it would mean a force-push. The link is recorded in the checkpoint
	// (LinkedCommits) and the commit is left alone.
	attachRecordLink
)

// attachLinkPlan is the commit an attach links to and how.
type attachLinkPlan struct {
	target *object.Commit
	mode   attachLinkMode
	// holder is a remote whose branches hold target, empty when none does (or,
	// when joining, none could be reached).
	holder string
	// remote is where the checkpoint is pushed now: holder, or the branch's own
	// remote when holder is an unrelated one. Empty when holder is.
	remote string
	// rewrite is target and the commits after it up to HEAD, oldest first
	// (attachAddTrailer only).
	rewrite []*object.Commit
	// checkedRemotes are the remotes asked whether they hold target.
	checkedRemotes []string
}

// planAttachLink resolves the target (HEAD unless --commit names another) and
// decides how to link it.
func planAttachLink(ctx context.Context, repo *git.Repository, headCommit *object.Commit, opts attachOptions) (attachLinkPlan, error) {
	target := headCommit
	if opts.Commit != "" {
		var err error
		if target, err = resolveAttachCommit(repo, opts.Commit); err != nil {
			return attachLinkPlan{}, err
		}
	}
	remotes := attachRemotesToCheck(ctx)
	if len(strategy.FinalCheckpointTrailers(ctx, target.Message)) > 0 {
		// Joining changes no history, so whether the commit is pushed only
		// decides when the checkpoint goes out: now if it is, since there may be
		// no later push of it, else with the next git push. A remote that can't
		// be reached leaves it for that push.
		holder, pushTo, _, err := remoteHoldingPushedCommit(ctx, target, remotes)
		if err != nil {
			return attachLinkPlan{}, err
		}
		return attachLinkPlan{target: target, mode: attachJoinExisting, remote: pushTo, holder: holder, checkedRemotes: remotes}, nil
	}
	holder, pushTo, unreachable, err := remoteHoldingPushedCommit(ctx, target, remotes)
	if err != nil {
		return attachLinkPlan{}, err
	}
	if holder != "" {
		return attachLinkPlan{target: target, mode: attachRecordLink, remote: pushTo, holder: holder, checkedRemotes: remotes}, nil
	}
	if len(unreachable) > 0 {
		// Absence from a remote we couldn't reach proves nothing; rewriting a
		// commit someone already pushed is what this rule exists to prevent.
		return attachLinkPlan{}, fmt.Errorf("couldn't confirm that commit %s isn't already pushed (could not reach %s), so it won't be rewritten; retry when the remote is reachable",
			target.Hash.String()[:12], strings.Join(unreachable, ", "))
	}
	chain, err := attachRewriteChain(ctx, repo, target, headCommit)
	if err != nil {
		return attachLinkPlan{}, err
	}
	return attachLinkPlan{target: target, mode: attachAddTrailer, rewrite: chain, checkedRemotes: remotes}, nil
}

// remoteHoldingPushedCommit returns a remote whose branches contain target
// (holder) and the remote to push its checkpoint to, both "" when none does,
// plus the remotes it could not reach. Remote-tracking refs
// can be stale — someone may have pushed this commit from another clone — and
// rewriting a shared commit is what attach must avoid, so remotes are
// refreshed first, then asked directly: tracking refs may not cover every
// branch (single-branch clones, narrowed refspecs).
func remoteHoldingPushedCommit(ctx context.Context, target *object.Commit, remotes []string) (holder, pushTo string, unreachable []string, err error) {
	fetchRemotesForAttach(ctx, remotes)
	if holder, pushTo, err = remoteHoldingCommit(ctx, target, remotes); err != nil || holder != "" {
		return holder, pushTo, nil, err
	}
	holder, unreachable = remoteContainingCommit(ctx, target, remotes)
	return holder, holder, unreachable, nil
}

// checkpointLinkedTo finds the most recent checkpoint whose recorded links
// name target, reading remote-discovered stubs for theirs. A listing failure
// finds none.
func checkpointLinkedTo(ctx context.Context, store cpkg.PersistentStore, target *object.Commit) (id.CheckpointID, bool) {
	infos, err := store.List(ctx)
	if err != nil {
		logging.Debug(ctx, "attach: listing checkpoints for a recorded link failed", slog.String("error", err.Error()))
		return id.EmptyCheckpointID, false
	}
	linked := cpkg.CheckpointsLinkedToWithStubs(ctx, store, infos, target.Hash.String(), target.Committer.When)
	if len(linked) == 0 {
		return id.EmptyCheckpointID, false
	}
	return linked[0], true
}

// attachFetchTimeout bounds the remote refresh attach does before deciding
// whether a commit is pushed.
const attachFetchTimeout = 30 * time.Second

// attachRemotes lists the repository's remotes.
func attachRemotes(ctx context.Context) []string {
	out, err := exec.CommandContext(ctx, "git", "remote").Output()
	if err != nil {
		return nil
	}
	return strings.Fields(string(out))
}

